import Link from "next/link";
import { getCategoryUrlSlugFromWpSlug, type PostListItem } from "@/lib/api";

interface TrendingSidebarProps {
  posts: PostListItem[];
  currentSlug?: string;
  currentPost?: { title: string; shareUrl: string };
}

export default function TrendingSidebar({ posts, currentSlug }: TrendingSidebarProps) {
  const relatedPosts = currentSlug ? posts.filter((p) => p.slug !== currentSlug) : posts;
  const list = relatedPosts.slice(0, 8);

  return (
    <aside className="w-full shrink-0 self-start rounded-surface bg-sidebar-bg p-panel lg:sticky lg:top-[150px] lg:w-[320px]">
      <ul className="divide-y divide-border">
        {list.map((post) => (
          <li key={post.id} className="py-3 first:pt-0">
            <Link
              href={`/${getCategoryUrlSlugFromWpSlug(post.categorySlug)}/${post.slug}`}
              prefetch={false}
              className="group block"
            >
              <span className="text-muted text-xs font-semibold uppercase tracking-wide">
                {post.categoryName}
              </span>
              <h3 className="text-foreground font-bold text-sm mt-0.5 line-clamp-2 group-hover:text-accent transition-colors">
                {post.title}
              </h3>
            </Link>
          </li>
        ))}
      </ul>
    </aside>
  );
}
